// 32-bit ZigZag Encoder
uint32_t encodeZigZag32(int32_t n) {
    return static_cast<uint32_t>((n << 1) ^ (n >> 31));
}

// 32-bit ZigZag Decoder
int32_t decodeZigZag32(uint32_t n) {
    return static_cast<int32_t>((n >> 1) ^ -(static_cast<int32_t>(n & 1)));
}

